    event OrderCancelled(bytes32 indexed pairId, address indexed maker, uint256 amountA, uint256 amountB, bool isBuy, uint256 timestamp);
    event TokenPairAdded(bytes32 indexed pairId, address indexed tokenA, address indexed tokenB);
    event TokenPairRemoved(bytes32 indexed pairId, address indexed tokenA, address indexed tokenB);

    // Modifiers
    modifier onlyTokenPair(bytes32 pairId) {
        require(address(tokenPairs[pairId].tokenA) != address(0) && address(tokenPairs[pairId].tokenB) != address(0), "Token pair not found");
        _;
    }

    // Functions

    // Function to create a new trading pair
    function addTokenPair(IERC20 tokenA, IERC20 tokenB) external onlyOwner {
        require(address(tokenA) != address(0) && address(tokenB) != address(0), "Invalid token address");
        require(address(tokenA) != address(tokenB), "TokenA and TokenB must be different");
